try {
  const rawInput = $input.first();
  const item = rawInput.json;
  const body = item.body || item;
  const headers = item.headers || {};

  const correlationId = headers['x-correlation-id'] || `ai_req_${Date.now()}`;

  return [{
    json: {
      step: 2,
      stepName: 'Request Header & Security Guard',
      success: true,
      correlationId,
      timestamp: new Date().toISOString(),
      body
    }
  }];
} catch (err) {
  return [{
    json: {
      step: 2,
      success: false,
      error: `Security Check Error: ${err.message}`
    }
  }];
}

const item = $input.first().json;
if (!item.success) return [{ json: item }];

const body = item.body || {};
const requirement = body.requirement || body.requirementText || body.text || '';

if (typeof requirement !== 'string' || requirement.trim().length < 10) {
  return [{
    json: {
      step: 3,
      stepName: 'Requirement Text Validator',
      success: false,
      errorMessage: 'Nội dung yêu cầu quá ngắn (tối thiểu 10 ký tự) để AI có thể phân tích cấu trúc.',
      ...item
    }
  }];
}

return [{
  json: {
    step: 3,
    stepName: 'Requirement Text Validator',
    success: true,
    cleanRequirement: requirement.trim(),
    requirementLength: requirement.trim().length,
    ...item
  }
}];

const item = $input.first().json;
if (!item.success) return [{ json: item }];

const { cleanRequirement } = item;

const prompt = `Bạn là Chuyên gia Phân tích Nghiệp vụ Phần mềm (Senior Business Analyst & Scrum Master).
Nhiệm vụ của bạn: Hãy phân tích yêu cầu phần mềm dưới đây và bóc tách thành cấu trúc phân cấp chuẩn Agile 3 tầng:
1. Epic (Khối tính năng lớn)
2. User Story (Câu chuyện người dùng: As a... I want... So that...)
3. Task (Các đầu việc kỹ thuật cụ thể)

QUY TẮC BẮT BUỘC:
1. Chỉ trả về một đối tượng JSON hợp lệ duy nhất.
2. Tuyệt đối KHÔNG kèm giải thích, KHÔNG viết bất kỳ chữ nào ngoài JSON.
3. Cấu trúc JSON bắt buộc phải theo schema sau:
{
  "epics": [
    {
      "title": "Tên Epic",
      "description": "Mô tả tổng quan của Epic",
      "stories": [
        {
          "title": "Tên Story",
          "description": "Mô tả chi tiết Story",
          "priority": "High",
          "storyPoints": 3,
          "tasks": [
            {
              "title": "Tên Task kỹ thuật",
              "description": "Mô tả chi tiết cách triển khai task"
            }
          ]
        }
      ]
    }
  ]
}

YÊU CẦU CỦA NGƯỜI DÙNG CẦN PHÂN TÍCH:
"""
${cleanRequirement}
"""`;

return [{
  json: {
    step: 4,
    stepName: 'Agile Persona & Prompt Builder',
    success: true,
    systemPrompt: prompt,
    cleanRequirement,
    ...item
  }
}];

try {
  const inputItem = $input.first().json;
  let rawContent = inputItem.content || inputItem.text || inputItem.response || inputItem;

  if (typeof rawContent === 'object' && rawContent.parts) {
    rawContent = rawContent.parts[0]?.text || JSON.stringify(rawContent);
  } else if (typeof rawContent === 'object' && !rawContent.epics) {
    rawContent = JSON.stringify(rawContent);
  }

  return [{
    json: {
      step: 6,
      stepName: 'Raw Content Extractor',
      success: true,
      rawContent
    }
  }];
} catch (err) {
  return [{
    json: {
      step: 6,
      success: false,
      error: `Content Extraction Error: ${err.message}`
    }
  }];
}

const item = $input.first().json;
if (!item.success) return [{ json: item }];

let text = item.rawContent;
if (typeof text === 'object') {
  text = JSON.stringify(text);
}

let cleanedText = String(text).trim();
// Loại bỏ markdown code block format nếu có (```json ... ```)
cleanedText = cleanedText.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();

return [{
  json: {
    step: 7,
    stepName: 'Markdown Code Block Cleaner',
    success: true,
    cleanedText,
    ...item
  }
}];

const item = $input.first().json;
if (!item.success) return [{ json: item }];

let parsed = null;
try {
  parsed = JSON.parse(item.cleanedText);
} catch (err) {
  // Thử trích xuất khối JSON bên trong cặp ngoặc nhọn lớn nhất
  const match = item.cleanedText.match(/\{[\s\S]*\}/);
  if (match) {
    try {
      parsed = JSON.parse(match[0]);
    } catch (innerErr) {
      return [{
        json: {
          step: 8,
          stepName: 'JSON Syntax Parser & Repair Engine',
          success: false,
          errorMessage: `Không thể parse JSON từ AI: ${innerErr.message}`,
          rawResponse: item.cleanedText,
          ...item
        }
      }];
    }
  } else {
    return [{
      json: {
        step: 8,
        stepName: 'JSON Syntax Parser & Repair Engine',
        success: false,
        errorMessage: 'AI không trả về khối JSON hợp lệ.',
        rawResponse: item.cleanedText,
        ...item
      }
    }];
  }
}

return [{
  json: {
    step: 8,
    stepName: 'JSON Syntax Parser & Repair Engine',
    success: true,
    parsedData: parsed,
    ...item
  }
}];

const item = $input.first().json;
if (!item.success) return [{ json: item }];

const parsed = item.parsedData || {};
let epics = parsed.epics || parsed.data?.epics || [];

if (!Array.isArray(epics) || epics.length === 0) {
  return [{
    json: {
      step: 9,
      stepName: 'Hierarchy Completeness Validator',
      success: false,
      errorMessage: 'Dữ liệu JSON không chứa danh sách epics hợp lệ.',
      ...item
    }
  }];
}

// Chuẩn hóa đảm bảo mỗi Epic có stories, mỗi Story có tasks
const validatedEpics = epics.map((epic, eIdx) => {
  const stories = Array.isArray(epic.stories) ? epic.stories : (epic.user_stories || []);
  return {
    title: epic.title || epic.name || epic.summary || `Epic ${eIdx + 1}`,
    description: epic.description || epic.title || 'Mô tả Epic',
    stories: stories.map((story, sIdx) => {
      const tasks = Array.isArray(story.tasks) ? story.tasks : (story.subtasks || []);
      return {
        title: story.title || story.name || story.summary || `Story ${sIdx + 1}`,
        description: story.description || story.title || 'Mô tả Story',
        priority: story.priority || 'Medium',
        storyPoints: typeof story.storyPoints === 'number' ? story.storyPoints : 3,
        tasks: tasks.map((task, tIdx) => {
          const taskTitle = typeof task === 'string' ? task : (task.title || task.name || `Task ${tIdx + 1}`);
          const taskDesc = typeof task === 'object' ? (task.description || taskTitle) : taskTitle;
          return {
            title: taskTitle,
            description: taskDesc
          };
        })
      };
    })
  };
});

return [{
  json: {
    step: 9,
    stepName: 'Hierarchy Completeness Validator',
    success: true,
    validatedEpics,
    ...item
  }
}];

const item = $input.first().json;
if (!item.success) return [{ json: item }];

const { validatedEpics } = item;
let totalPoints = 0;

// Áp dụng thuật toán ước lượng Fibonacci (1, 2, 3, 5, 8)
const enrichedEpics = validatedEpics.map(epic => {
  const enrichedStories = epic.stories.map(story => {
    let points = story.storyPoints;
    if (!points || typeof points !== 'number') {
      const taskCount = story.tasks.length;
      if (taskCount <= 1) points = 1;
      else if (taskCount <= 2) points = 2;
      else if (taskCount <= 3) points = 3;
      else points = 5;
    }
    totalPoints += points;
    return {
      ...story,
      storyPoints: points
    };
  });

  return {
    ...epic,
    stories: enrichedStories
  };
});

return [{
  json: {
    step: 10,
    stepName: 'Agile Estimation & Points Calculator',
    success: true,
    enrichedEpics,
    totalPoints,
    ...item
  }
}];

const item = $input.first().json;

if (!item.success) {
  return [{
    json: {
      success: false,
      stepFailed: item.step,
      stepName: item.stepName,
      error: item.errorMessage || item.error || 'Phân tích yêu cầu thất bại',
      epics: []
    }
  }];
}

const { enrichedEpics, totalPoints } = item;
let totalStories = 0;
let totalTasks = 0;

for (const e of enrichedEpics) {
  totalStories += e.stories.length;
  for (const s of e.stories) {
    totalTasks += s.tasks.length;
  }
}

const summary = {
  epicsCount: enrichedEpics.length,
  storiesCount: totalStories,
  tasksCount: totalTasks,
  totalStoryPoints: totalPoints
};

return [{
  json: {
    success: true,
    epics: enrichedEpics,
    summary,
    content: JSON.stringify({ epics: enrichedEpics, summary })
  }
}];
